#include "stdlib/blas/ext/base/sleft_pad_edge.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/blas/base/shared.h"

/**
* Prepends elements to a single-precision floating-point strided array by repeating the leading edge element.
*
* @param N       number of indexed elements in `X`
* @param k       number of elements to pad
* @param X       input array
* @param strideX stride length for X
* @param Y       output array
* @param strideY stride length for Y
*/
void API_SUFFIX(stdlib_strided_sleft_pad_edge)( const CBLAS_INT N, CBLAS_INT k, const float *X, const CBLAS_INT strideX, float *Y, const CBLAS_INT strideY ) {
	CBLAS_INT offsetX;
	CBLAS_INT offsetY;

	if ( k < 0 ) {
		k = 0;
	}
	offsetX = stdlib_strided_stride2offset( N, strideX );
	offsetY = stdlib_strided_stride2offset( N + k, strideY );
	API_SUFFIX(stdlib_strided_sleft_pad_edge_ndarray)( N, k, X, strideX, offsetX, Y, strideY, offsetY );
}

/**
* Prepends elements to a single-precision floating-point strided array by repeating the leading edge element using alternative indexing semantics.
*
* @param N       number of indexed elements in `X`
* @param k       number of elements to pad
* @param X       input array
* @param strideX stride length for X
* @param offsetX starting index for X
* @param Y       output array
* @param strideY stride length for Y
* @param offsetY starting index for Y
*/
void API_SUFFIX(stdlib_strided_sleft_pad_edge_ndarray)( const CBLAS_INT N, CBLAS_INT k, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, float *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	CBLAS_INT ix;
	CBLAS_INT iy;
	float v;
	CBLAS_INT i;

	if ( N <= 0 ) {
		return;
	}
	if ( k < 0 ) {
		k = 0;
	}
	v = X[ offsetX ];
	iy = offsetY;
	for ( i = 0; i < k; i++ ) {
		Y[ iy ] = v;
		iy += strideY;
	}
	ix = offsetX;
	for ( i = 0; i < N; i++ ) {
		Y[ iy ] = X[ ix ];
		iy += strideY;
		ix += strideX;
	}
}
